  "database.ts":
    'import type {\n  DatabaseQuery,\n  DatabaseResult,\n  DatabaseRow,\n  MarinaRuntimeBinding,\n} from "./contract.js";\nimport {\n  containsDatabaseTransactionControl,\n  MAX_DATABASE_PARAMETER_BYTES,\n  MAX_DATABASE_PARAMETERS,\n  MAX_DATABASE_QUERY_BYTES,\n  MAX_DATABASE_TRANSACTION_QUERIES,\n} from "./contract.js";\nimport { MarinaRuntimeError } from "./error.js";\nimport { invokeRuntime } from "./invoke.js";\n\nconst encoder = new TextEncoder();\nconst MAX_VALUE_DEPTH = 32;\n\nfunction invalid(message: string): never {\n  throw new MarinaRuntimeError({ code: "INVALID_INPUT", message, retryable: false });\n}\n\nfunction assertJsonValue(value: unknown, depth = 0, seen = new Set<object>()): void {\n  if (depth > MAX_VALUE_DEPTH) invalid("database parameters are nested too deeply");\n  if (\n    value === null ||\n    typeof value === "string" ||\n    typeof value === "boolean" ||\n    (typeof value === "number" && Number.isFinite(value))\n  )\n    return;\n  if (!value || typeof value !== "object")\n    invalid("database parameters must contain only JSON-compatible values");\n  if (seen.has(value)) invalid("database parameters must not contain cycles");\n  seen.add(value);\n  if (Array.isArray(value)) {\n    for (const item of value) assertJsonValue(item, depth + 1, seen);\n  } else {\n    const prototype = Object.getPrototypeOf(value);\n    if (prototype !== Object.prototype && prototype !== null)\n      invalid("database parameters must contain only plain JSON objects");\n    for (const item of Object.values(value)) assertJsonValue(item, depth + 1, seen);\n  }\n  seen.delete(value);\n}\n\nfunction jsonBytes(value: unknown): number {\n  assertJsonValue(value);\n  let serialized: string;\n  try {\n    serialized = JSON.stringify(value);\n  } catch {\n    invalid("database parameters must be JSON serializable");\n  }\n  if (serialized === undefined) invalid("database parameters must be JSON serializable");\n  return encoder.encode(serialized).byteLength;\n}\n\n/** Validate one provider-neutral parameterized Postgres query. Runtime SQL is\n * app-authored, but values remain separate so callers never need to interpolate\n * request data into SQL text. The broker repeats these checks at its boundary. */\nexport function assertDatabaseQuery(value: DatabaseQuery): DatabaseQuery {\n  if (!value || typeof value !== "object" || Array.isArray(value))\n    invalid("database query must be an object");\n  if (typeof value.text !== "string" || value.text.trim().length === 0)\n    invalid("database query text must not be empty");\n  if (value.text.includes("\\0")) invalid("database query text must not contain null bytes");\n  if (containsDatabaseTransactionControl(value.text))\n    invalid("database transactions are managed by the Marina runtime");\n  if (encoder.encode(value.text).byteLength > MAX_DATABASE_QUERY_BYTES)\n    invalid(`database query text must not exceed ${String(MAX_DATABASE_QUERY_BYTES)} bytes`);\n  if (!Array.isArray(value.params)) invalid("database query parameters must be an array");\n  if (value.params.length > MAX_DATABASE_PARAMETERS)\n    invalid(`database queries may contain at most ${String(MAX_DATABASE_PARAMETERS)} parameters`);\n  if (jsonBytes(value.params) > MAX_DATABASE_PARAMETER_BYTES)\n    invalid(\n      `database query parameters must not exceed ${String(MAX_DATABASE_PARAMETER_BYTES)} bytes`,\n    );\n  return value;\n}\n\nexport interface MarinaDatabase {\n  /** Execute one parameterized statement against this app\'s private schema. */\n  query<Row extends DatabaseRow = DatabaseRow>(\n    text: string,\n    params?: DatabaseQuery["params"],\n  ): Promise<DatabaseResult<Row>>;\n\n  /** Execute a bounded list of statements atomically. Interactive transaction\n   * callbacks are intentionally absent so the contract works across edge and\n   * future non-Cloudflare substrates. */\n  transaction<Row extends DatabaseRow = DatabaseRow>(\n    queries: readonly DatabaseQuery[],\n  ): Promise<DatabaseResult<Row>[]>;\n}\n\nexport function createDatabase(binding: MarinaRuntimeBinding): MarinaDatabase {\n  return {\n    async query(text, params = []) {\n      const query = assertDatabaseQuery({ text, params });\n      return invokeRuntime(binding, "db", "query", query);\n    },\n\n    async transaction(queries) {\n      if (!Array.isArray(queries) || queries.length === 0)\n        invalid("database transaction must contain at least one query");\n      if (queries.length > MAX_DATABASE_TRANSACTION_QUERIES)\n        invalid(\n          `database transactions may contain at most ${String(MAX_DATABASE_TRANSACTION_QUERIES)} queries`,\n        );\n      const validated = queries.map((query) => assertDatabaseQuery(query));\n      return invokeRuntime(binding, "db", "transaction", { queries: validated });\n    },\n  };\n}\n',
